def solve(weights, values, capacity):
    """Return the maximum total value achievable with given weights and values within capacity.
    Each item can be used at most once (0/1 knapsack).
    """
    n = len(weights)
    if n == 0 or capacity <= 0:
        return 0
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        if w > capacity:
            # cannot fit this item at any capacity
            continue
        for cap in range(capacity, w - 1, -1):
            new_val = dp[cap - w] + v
            if new_val > dp[cap]:
                dp[cap] = new_val
    return dp[capacity]

