def solve(n):
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)  # 0..limit inclusive
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
