def solve(s):
    """Run‑length encode *s*.
    Accepts any iterable (string, list, tuple, etc.) and returns a list of
    ``[item, count]`` pairs. Non‑iterable inputs yield an empty list.
    """
    try:
        seq = list(s)
    except Exception:
        return []
    if not seq:
        return []
    res = []
    prev = seq[0]
    count = 1
    for ch in seq[1:]:
        if ch == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = ch
            count = 1
    res.append([prev, count])
    return res

