def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses the patience sorting O(n log n) algorithm.
    """
    from bisect import bisect_left
    tails = []
    for x in nums:
        # Find position to replace in tails
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

