def solve(s: str) -> int:
    """Return length of longest substring without repeating characters.
    Uses sliding window with last occurrence map.
    """
    last_idx = {}
    start = 0
    max_len = 0
    for i, ch in enumerate(s):
        if ch in last_idx and last_idx[ch] >= start:
            start = last_idx[ch] + 1
        last_idx[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    Returns the integer result.
    """
    stack = []
    for tok in tokens:
        if tok in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # '/'
                # Python division truncates toward negative infinity for //, but we need truncate toward zero.
                # Use int(a / b) which truncates toward zero.
                stack.append(int(a / b))
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

