def solve(coins, amount):
    """Return the fewest number of coins needed to make up amount.
    Unlimited supply of each coin value. Return -1 if impossible.
    Uses DP with O(amount * len(coins)) time.
    """
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non-positive coin values
    coins = [c for c in coins if isinstance(c, int) and c > 0]
    if not coins:
        return -1
    # DP array where dp[i] = min coins for amount i, init with sentinel
    max_val = amount + 1
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a:
                if dp[a - c] + 1 < dp[a]:
                    dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != max_val else -1

